// Customize the background used each turn!
// This function runs at the start of each turn.
// The default background is available as DEFAULT_BG.
// Additional backgrounds are available as ADDITIONAL_BG_#,
// e.g. ADDITIONAL_BG_1 for the first added background.

int PickBackground() {
    return DEFAULT_BG;
}

// Customize the background music used each turn!
// This function runs whenever the board music starts playing.
// Custom tracks you've added are available as MUSIC_TRACK_INDEX_#,
// e.g. MUSIC_TRACK_INDEX_1 for the first added custom song.
// (If you aren't using custom music, then only MUSIC_TRACK_INDEX_1
// exists and it is set to the in-game music index you chose.)

int PickAudioIndex() {
    return MUSIC_TRACK_INDEX_1;
}

#include <ultra64.h>
extern int GetPlayerStruct(int);
extern void ShowMessage(int, char *, int, int, int, int, int);
int x = 5;
float f = 1.5;
char *msg = "Hello";
static short arr[4] = { 1, 2, 3, 4 };
struct S { int a; char b; } s;
void main() {
  int i;
  for (i = 0; i < 4; i++) { x += GetPlayerStruct(i) * 3 + arr[i]; }
  f = f * x - 2.0f / f;
  if (f < 3.0f && f >= -1.0f) { x = (int)f; }
  s.a = x % 7; s.b = 'c';
  ShowMessage(-1, msg, 0, 0, 0, 0, 0);
  switch (x) { case 1: x = 2; break; case 5: x = 9; break; default: x = -x; }
  while (x > 0) x >>= 1;
  do { x ^= 0xFF; } while (x & 1);
}

// PARAM: Number|coins
// PARAM: Space|target
void main() {
  int c = COINS_PARAM;
  unsigned int u = 0xFFFFFFFF;
  u = u / 3 + (u >> 4);
  c = c ? c * 2 : -1;
}

